from ortools.sat.python import cp_model
import json

# Input data
X = -1
game_data = [  # 0-8: number of mines around, -1: not opened
    [2, 3, X, 2, 2, X, 2, 1],
    [X, X, 4, X, X, 4, X, 2],
    [X, X, X, X, X, X, 4, X],
    [X, 5, X, 6, X, X, X, 2],
    [2, X, X, X, 5, 5, X, 2],
    [1, 3, 4, X, X, X, 4, X],
    [0, 1, X, 4, X, X, X, 3],
    [0, 1, 2, X, 2, 3, X, 2]
]

rows = len(game_data)
cols = len(game_data[0])

# Model definition
model = cp_model.CpModel()

# Decision Variables
# For each cell that is X (-1), create a boolean variable indicating if it is a mine (1) or not (0)
mines = {}
for r in range(rows):
    for c in range(cols):
        if game_data[r][c] == X:
            mines[(r, c)] = model.NewBoolVar(f'mine_{r}_{c}')

# Helper function to get neighbors coordinates
def neighbors(r, c):
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not (nr == r and nc == c):
                    yield nr, nc

# Constraints
# For each cell with a number (0-8), the sum of mines in its neighbors must equal that number
for r in range(rows):
    for c in range(cols):
        if game_data[r][c] >= 0:
            # Collect neighbor mine variables or known mine status
            neighbor_mines = []
            for nr, nc in neighbors(r, c):
                if game_data[nr][nc] == X:
                    neighbor_mines.append(mines[(nr, nc)])
                else:
                    # Known cell, if it is a number, it is not a mine (0)
                    # So no need to add anything
                    pass
            # The sum of mines in neighbors must be equal to the clue number
            model.Add(sum(neighbor_mines) == game_data[r][c])

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    # Prepare output: a 2D list of same size as game_data with 1 if mine, 0 if not
    mines_output = []
    for r in range(rows):
        row_mines = []
        for c in range(cols):
            if game_data[r][c] == X:
                row_mines.append(solver.Value(mines[(r, c)]))
            else:
                # Known cells are not mines
                row_mines.append(0)
        mines_output.append(row_mines)
    solution = {
        'mines': mines_output
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
```

